import{_ as t,o as a,c as d,ag as r}from"./chunks/framework.Dh3ZG9qC.js";const m=JSON.parse('{"title":"API 与 SDK 导航","description":"","frontmatter":{},"headers":[],"relativePath":"reference/api.md","filePath":"reference/api.md","lastUpdated":null}'),o={name:"reference/api.md"};function i(c,e,s,n,p,l){return a(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="api-与-sdk-导航" tabindex="-1">API 与 SDK 导航 <a class="header-anchor" href="#api-与-sdk-导航" aria-label="Permalink to &quot;API 与 SDK 导航&quot;">​</a></h1><p>Gamer 的 Web 界面通过 HTTP API 与 WebSocket 连接 Core，实时画面和输入使用 WebRTC。插件通过受权限约束的 SDK 使用宿主能力。</p><h2 id="http-api-分组" tabindex="-1">HTTP API 分组 <a class="header-anchor" href="#http-api-分组" aria-label="Permalink to &quot;HTTP API 分组&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>主要用途</th></tr></thead><tbody><tr><td><code>/api/devices</code></td><td>设备管理、扫描与控制</td></tr><tr><td><code>/api/packages</code></td><td>配置包、插件资源、导入导出</td></tr><tr><td><code>/api/runs</code></td><td>统一运行入口、查询与取消</td></tr><tr><td><code>/api/runners</code></td><td>执行器、入口 schema 与函数目录</td></tr><tr><td><code>/api/tasks</code>、<code>/api/task-presets</code></td><td>调度任务与预设</td></tr><tr><td><code>/api/media</code>、<code>/api/recording</code></td><td>媒体、帧索引与录制</td></tr><tr><td><code>/api/extensions</code></td><td>插件安装、生命周期、能力与 UI</td></tr><tr><td><code>/api/logs</code></td><td>运行日志</td></tr><tr><td><code>/api/system</code></td><td>服务信息与托管更新状态</td></tr><tr><td><code>/ws/device/:id</code></td><td>WebRTC 信令</td></tr></tbody></table><p>业务 API 需要会话认证。写请求还需遵循同源检查；使用前端开发代理时不要随意改变 Origin 与 Host 的关系。</p><p><code>POST /api/runs</code> 接受执行器、入口、参数、设备与配置上下文，成功受理返回 <code>202</code> 和 <code>run_id</code>。同一设备已有活动运行时返回冲突，不能以并发启动绕过设备运行守卫。</p><h2 id="插件-host-api" tabindex="-1">插件 Host API <a class="header-anchor" href="#插件-host-api" aria-label="Permalink to &quot;插件 Host API&quot;">​</a></h2><p>WASM 插件的宿主契约定义在 <code>server/wit/</code>，能力调用由权限声明与宿主实现共同约束。配置资源寻址使用配置 ID、插件 ID、相对路径；保存时使用版本检查，避免覆盖其他编辑。</p><p>完整方法、权限、数据类型与 manifest 说明请查阅：</p><ul><li><a href="https://github.com/jesongit/gamer/blob/main/docs/reference/PLUGIN_API.md" target="_blank" rel="noreferrer">Host API 参考</a></li><li><a href="https://github.com/jesongit/gamer/blob/main/docs/guides/plugin-dev.md" target="_blank" rel="noreferrer">插件开发指南</a></li><li><a href="https://github.com/jesongit/gamer/tree/main/server/wit" target="_blank" rel="noreferrer">WIT 权威定义</a></li><li><a href="https://github.com/jesongit/gamer/tree/main/sdk/examples" target="_blank" rel="noreferrer">独立 SDK 示例</a></li></ul><p>接口与运行参数以当前服务端返回的 schema 为准。新增业务能力优先复用既有 capability 与插件公开动作，保持 Core 对具体脚本语言和项目格式无关。</p>',11)])])}const b=t(o,[["render",i]]);export{m as __pageData,b as default};
